// Walk an entire face loop
int start = primhedge(0, @primnum);
int cur   = start;
int vtx_count = 0;
do {
    vtx_count++;
    cur = hedge_next(0, cur);
} while (cur != start);
// vtx_count now equals the number of vertices in this primitive
```

